H.background();
const ang = (P.bond * Math.PI / 180);
const cx = H.W * 0.5, cy = H.H * 0.55, L = 130;
const dipMag = 1.0;
const half = ang / 2;
const ax = -Math.sin(half), ay = Math.cos(half);
const bx = Math.sin(half), by = Math.cos(half);
const netx = dipMag * (ax + bx);
const nety = dipMag * (ay + by);
const net = Math.sqrt(netx * netx + nety * nety);
const wob = 1 + 0.12 * Math.sin(t * 1.5);
const cAx = cx + L * ax, cAy = cy - L * ay;
const cBx = cx + L * bx, cBy = cy - L * by;
H.line(cx, cy, cAx, cAy, { color: H.colors.grid, width: 3 });
H.line(cx, cy, cBx, cBy, { color: H.colors.grid, width: 3 });
H.circle(cx, cy, 18, { fill: H.colors.accent, stroke: H.colors.ink, width: 2 });
H.text("X", cx, cy, { color: H.colors.bg, size: 14, align: "center", baseline: "middle", weight: 700 });
H.circle(cAx, cAy, 14, { fill: H.colors.violet });
H.circle(cBx, cBy, 14, { fill: H.colors.violet });
const s = 70 * wob;
H.arrow(cAx, cAy, cAx - s * ax, cAy + s * ay, { color: H.colors.warn, width: 3 });
H.arrow(cBx, cBy, cBx - s * bx, cBy + s * by, { color: H.colors.warn, width: 3 });
const ns = net * 70 * wob;
const polar = net > 0.05;
if (polar) {
  H.arrow(cx, cy, cx - ns * (netx / (net || 1)), cy + ns * (nety / (net || 1)), { color: H.colors.good, width: 5 });
}
H.text("Net molecular dipole = vector sum of bond dipoles", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Bonds add as VECTORS; symmetry can make them cancel.", 24, 52, { color: H.colors.sub, size: 13 });
H.text("bond angle = " + P.bond.toFixed(0) + " deg", 24, 90, { color: H.colors.sub, size: 13 });
H.text("|net dipole| = " + net.toFixed(2) + "  ->  " + (polar ? "POLAR" : "NONPOLAR"), 24, 110, { color: polar ? H.colors.good : H.colors.sub, size: 13 });
H.legend([{ label: "bond dipole", color: H.colors.warn }, { label: "net dipole", color: H.colors.good }], 24, 130);
